#!/usr/bin/env bash
# Tags de personnes : tableau des droits (galeries, carrousel, blocs « Galerie d'images ») et modale des tags.
# Prérequis : apply-docs-tags-backend.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-tags-tableau.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null | grep -qF "candidates: adminProcedure"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Un verdict calculé, jamais stocké" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tags-backend.sh puis apply-docs-tags-backend.sh"; exit 1; }
MODIFIED=("apps/web/src/features/admin/galleries/components/MediaItemsEditor.tsx" "apps/web/src/features/page-builder/PageBuilder.tsx" "apps/web/src/features/page-builder/PageBuilderContext.tsx" "apps/web/src/features/page-builder/blocks/image-gallery/editor.client.tsx" "apps/web/src/features/page-builder/components/MediaListEditor.tsx" "apps/web/src/features/social/InstructorBioEditor.tsx" "e2e/data.mjs" "e2e/prepare.mjs" "packages/backend/src/modules/mediaPeople/mediaPeople.service.ts" "packages/backend/src/modules/mediaPeople/router.ts")
CREATED=("apps/web/src/features/admin/media-people/MediaTagsDialog.tsx" "apps/web/src/features/admin/media-people/RightsBadges.tsx" "e2e/tags-personnes-tableau.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/features/admin/media-people" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "candidates: adminProcedure" "packages/backend/src/modules/mediaPeople/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/media-people"
